def _backfill_familias() -> None:
    """Por cada owner_id con hijos sin familia: crea una familia, al owner como
    admin, y asigna family_id a sus hijos. Idempotente (solo toca family_id NULL)."""
    conn = op.get_bind()
    md = sa.MetaData()
    family_t = sa.Table(
        "family", md,
        sa.Column("id", sa.Integer, primary_key=True),
        sa.Column("name", sa.String, nullable=True),
        sa.Column("created_at", sa.DateTime),
    )
    member_t = sa.Table(
        "familymember", md,
        sa.Column("id", sa.Integer, primary_key=True),
        sa.Column("family_id", sa.Integer),
        sa.Column("chat_id", sa.BigInteger),
        sa.Column("display_name", sa.String, nullable=True),
        sa.Column("role", sa.String),
        sa.Column("created_at", sa.DateTime),
    )
    child_t = sa.Table(
        "child", md,
        sa.Column("id", sa.Integer, primary_key=True),
        sa.Column("owner_id", sa.BigInteger),
        sa.Column("family_id", sa.Integer, nullable=True),
    )
    now = datetime.utcnow()
    owners = conn.execute(
        sa.select(child_t.c.owner_id).where(child_t.c.family_id.is_(None)).distinct()
    ).scalars().all()
    for owner in owners:
        fam_id = conn.execute(
            family_t.insert().values(created_at=now)
        ).inserted_primary_key[0]
        conn.execute(
            member_t.insert().values(
                family_id=fam_id, chat_id=owner, role="admin", created_at=now
            )
        )
        conn.execute(
            child_t.update()
            .where(sa.and_(child_t.c.owner_id == owner, child_t.c.family_id.is_(None)))
            .values(family_id=fam_id)
        )


